import type { RouteData, RouteManeuverStep } from '../types/route';
import type { RerouteResponse } from '../api/types';

// ============================================================================
// CANONICAL TYPES FOR DETERMINISTIC DEMO MODE
// ============================================================================

export type AccessibilityStatus = 'OPEN' | 'RESTRICTED' | 'CLOSED';
export type RiskLevel = 'LOW' | 'MEDIUM' | 'HIGH';

export interface RouteMetrics {
  distanceKm: number;
  durationMinutes: number;
  averageSpeedKmh: number;
  maxDistance135Limit: number;
  maxTime135Limit: number;
  withinDistanceConstraint: boolean;
  withinTimeConstraint: boolean;
  isViable: boolean;
}

export interface RiskAssessment {
  score: number; // 0 to 100
  level: RiskLevel;
  primaryRiskFactor: string;
  weatherFactor: string;
  slopeStabilityFactor: string;
}

export type HazardType =
  | 'LANDSLIDE'
  | 'FOG'
  | 'FLOOD'
  | 'ROAD_RESTRICTION'
  | 'ACCIDENT'
  | 'ROCKFALL';

export interface Hazard {
  id: string;
  name: string;
  title?: string;
  type: HazardType;
  source?: 'ACCESSIBILITY' | 'ALERT' | 'INCIDENT';
  distanceAheadKm: number;
  severity: 'CRITICAL' | 'WARNING' | 'INFO';
  description: string;
  status: 'ACTIVE' | 'MONITORING' | 'RESOLVING';
  locationText: string;
  coordinates: [number, number]; // [lng, lat]
  corridorKmMarker?: number;
  reportedAt: string;
}

export interface Incident {
  id: string;
  type:
    | 'Landslide'
    | 'Fallen Rocks'
    | 'Flash Flood'
    | 'Road Obstruction'
    | 'Overturned Truck'
    | 'Waterlogging'
    | 'Accident';
  description: string;
  coordinates: {
    latitude: number;
    longitude: number;
  };
  reportedAt: string;
  status: 'REPORTED' | 'VERIFIED' | 'RESOLVED';
  isSimulated?: boolean;
}

export interface RerouteScenario {
  criticalAlert: {
    id: string;
    title: string;
    description: string;
    locationName: string;
    severity: 'CRITICAL';
    timestamp: string;
    affectedKmMarker: number;
  };
  rerouteData: RerouteResponse;
}

export interface ReportTemplate {
  id: Incident['type'];
  label: string;
  icon: string;
  defaultDescription: string;
  quickChips: string[];
}

export interface SOSResponderUnit {
  unit: string;
  status: string;
}

export interface SOSResponse {
  success: boolean;
  sosId: string;
  timestamp: string;
  coordinates: string;
  status: string;
  nearestCheckpost: string;
  etaMinutes: number;
  responders: SOSResponderUnit[];
  isSimulated: boolean;
}

export type CandidateRouteKind = 'low' | 'medium' | 'high' | 'safe' | 'fastest';

export interface CandidateRouteOption {
  id: string;
  kind: CandidateRouteKind;
  name: string;
  via: string;
  distanceKm: number;
  durationMinutes: number;
  safetyScore: number; // 0 to 100
  riskLevel: RiskLevel;
  accessibilityStatus: AccessibilityStatus;
  isRecommended: boolean;
  tag: string;
  whyThisRoute: string;
  routeData: RouteData;
}

export interface EvaluatedRouteOption extends CandidateRouteOption {
  metrics: RouteMetrics;
  whyThisRouteBullets: string[];
}

export interface Corridor {
  id: string;
  corridorName: string;
  region: string;
  origin: {
    name: string;
    subtitle: string;
    coordinates: [number, number]; // [lng, lat]
  };
  destination: {
    name: string;
    subtitle: string;
    coordinates: [number, number]; // [lng, lat]
  };
  candidateRoutes: CandidateRouteOption[];
  whatsAheadHazards: Hazard[];
  dynamicRerouteScenario: RerouteScenario;
}

export type DemoCorridorPlan = Corridor;

// ============================================================================
// DETERMINISTIC 1.35x CONSTRAINT & RECOMMENDATION ENGINE
// ============================================================================

export function evaluateCandidateRoutes(candidates: CandidateRouteOption[]): {
  evaluatedRoutes: EvaluatedRouteOption[];
  recommendedIndex: number;
  fastestDistance: number;
  fastestTime: number;
  maxDistance135: number;
  maxTime135: number;
} {
  if (!candidates || candidates.length === 0) {
    return {
      evaluatedRoutes: [],
      recommendedIndex: 0,
      fastestDistance: 0,
      fastestTime: 0,
      maxDistance135: 0,
      maxTime135: 0,
    };
  }

  // Baseline: Find the shortest/fastest route to act as 1.0x baseline reference
  const fastestDistance = Math.min(...candidates.map((c) => c.distanceKm));
  const fastestTime = Math.min(...candidates.map((c) => c.durationMinutes));

  const maxDistance135 = Number((fastestDistance * 1.35).toFixed(1));
  const maxTime135 = Number((fastestTime * 1.35).toFixed(1));

  let bestViableScore = -1;
  let recommendedIndex = 0;

  const evaluatedRoutes: EvaluatedRouteOption[] = candidates.map((candidate, idx) => {
    const withinDistanceConstraint = candidate.distanceKm <= maxDistance135;
    const withinTimeConstraint = candidate.durationMinutes <= maxTime135;
    const isRoadOpen = candidate.accessibilityStatus !== 'CLOSED';
    const isViable = isRoadOpen && withinDistanceConstraint && withinTimeConstraint;

    // Favor highest safety score among viable routes (Low Risk)
    if (isViable && candidate.safetyScore > bestViableScore) {
      bestViableScore = candidate.safetyScore;
      recommendedIndex = idx;
    }

    const bullets: string[] = [];

    if (candidate.kind === 'low' || candidate.kind === 'safe') {
      bullets.push('🟢 LOW RISK: Assessed Safety Score ' + candidate.safetyScore + '/100 (Recommended)');
      bullets.push('✓ Road is fully OPEN with active clearance and median barriers');
      bullets.push('✓ Avoids high-vulnerability landslide & fog hotspot zones');
    } else if (candidate.kind === 'medium') {
      bullets.push('🟡 MEDIUM RISK: Balanced route with moderate detour distance');
      bullets.push('✓ Road is usable with active daylight monitoring');
      bullets.push('⚠ Intermediate mountain bypass; minor asphalt roughness');
    } else {
      bullets.push('🔴 HIGH RISK: Direct alignment with elevated hazard vulnerability');
      bullets.push('⚠ Assessed Safety Score ' + candidate.safetyScore + '/100 (High Risk)');
      if (candidate.accessibilityStatus === 'RESTRICTED') {
        bullets.push('⚠ Road status is RESTRICTED: Speed/weight controls in effect');
      } else if (candidate.accessibilityStatus === 'CLOSED') {
        bullets.push('✗ Road status is CLOSED: Impassable obstruction reported');
      }
    }

    if (withinDistanceConstraint) {
      const distDelta = candidate.distanceKm - fastestDistance;
      bullets.push(
        distDelta <= 0
          ? '✓ Baseline shortest distance (' + candidate.distanceKm + ' km ≤ 1.35× limit of ' + maxDistance135 + ' km)'
          : '✓ Within 1.35× distance limit (' + candidate.distanceKm + ' km ≤ ' + maxDistance135 + ' km, +' + distDelta.toFixed(1) + ' km)'
      );
    } else {
      bullets.push('✗ Exceeds 1.35× distance limit (' + candidate.distanceKm + ' km > ' + maxDistance135 + ' km)');
    }

    if (withinTimeConstraint) {
      bullets.push('✓ Within 1.35× travel time (' + candidate.durationMinutes + 'm ≤ ' + maxTime135 + 'm)');
    } else {
      bullets.push('✗ Exceeds 1.35× travel time limit (' + candidate.durationMinutes + 'm > ' + maxTime135 + 'm)');
    }

    const metrics: RouteMetrics = {
      distanceKm: candidate.distanceKm,
      durationMinutes: candidate.durationMinutes,
      averageSpeedKmh: Math.round((candidate.distanceKm / (candidate.durationMinutes / 60)) * 10) / 10,
      maxDistance135Limit: maxDistance135,
      maxTime135Limit: maxTime135,
      withinDistanceConstraint,
      withinTimeConstraint,
      isViable,
    };

    return {
      ...candidate,
      isRecommended: false,
      metrics,
      whyThisRouteBullets: bullets,
    };
  });

  if (evaluatedRoutes[recommendedIndex]) {
    evaluatedRoutes[recommendedIndex].isRecommended = true;
  }

  return {
    evaluatedRoutes,
    recommendedIndex,
    fastestDistance,
    fastestTime,
    maxDistance135,
    maxTime135,
  };
}

