export function getDemoCorridors(): Corridor[] {
  return DEMO_CORRIDORS;
}

export function getDemoCorridorById(id: string): Corridor {
  const found = DEMO_CORRIDORS.find((c) => c.id === id);
  return found || DEMO_CORRIDORS[0];
}

export const getDemoCorridor = getDemoCorridorById;

export function getDemoSosReceipt(
  coordsInput?: string | { latitude: number; longitude: number }
): SOSResponse {
  let formattedCoords = '25.9015° N, 91.8785° E';
  if (typeof coordsInput === 'string') {
    formattedCoords = coordsInput;
  } else if (coordsInput && typeof coordsInput.latitude === 'number') {
    formattedCoords = `${coordsInput.latitude.toFixed(4)}° N, ${coordsInput.longitude.toFixed(4)}° E`;
  }

  return {
    success: true,
    sosId: 'SOS-SAURA-782190',
    timestamp: '2026-09-28T10:45:00.000Z',
    coordinates: formattedCoords,
    status: 'SOS DISPATCHED',
    nearestCheckpost: 'BRO Highway Post 14 (Umling)',
    etaMinutes: 12,
    responders: [
      { unit: 'Highway Patrol Unit 4', status: 'En route (ETA 8 mins)' },
      { unit: '108 Emergency Ambulance', status: 'Dispatched (ETA 12 mins)' },
      { unit: 'BRO Heavy Clearance Unit 12', status: 'Standby mobilization' },
    ],
    isSimulated: true,
  };
}
